//! Programmatic folder builder.
//!
//! For the typed builder generated by [`crate::folder!`], use
//! `<schema>::Folder::builder()` directly. This module is the
//! macro-less alternative for callers building folders dynamically.

use std::path::{Path, PathBuf};

use crate::content_source::ContentSource;
use crate::error::FolderError;
use crate::node::FileType;

/// A single entry to materialize in a [`FolderBuilder`].
#[derive(Debug)]
pub struct FolderEntry {
  /// Relative path within the folder.
  pub path: PathBuf,
  /// File or folder.
  pub kind: EntryKind,
  /// How to populate the entry.
  pub source: ContentSource,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EntryKind {
  File(FileType),
  Folder,
}

impl FolderEntry {
  pub fn file(path: impl Into<PathBuf>, file_type: FileType, source: ContentSource) -> Self {
    Self {
      path: path.into(),
      kind: EntryKind::File(file_type),
      source,
    }
  }

  pub fn folder(path: impl Into<PathBuf>, source: ContentSource) -> Self {
    Self {
      path: path.into(),
      kind: EntryKind::Folder,
      source,
    }
  }

  pub fn apply(&self, root: &Path) -> Result<(), FolderError> {
    let dest = root.join(&self.path);
    if let Some(parent) = dest.parent() {
      std::fs::create_dir_all(parent).map_err(|source| FolderError::Io {
        path: parent.to_path_buf(),
        source,
      })?;
    }

    match self.kind {
      EntryKind::File(file_type) => {
        self.source.apply_file(&dest)?;

        #[cfg(unix)]
        if matches!(file_type, FileType::Shell) {
          use std::os::unix::fs::PermissionsExt;
          let mut perms = std::fs::metadata(&dest)
            .map_err(|source| FolderError::Io {
              path: dest.clone(),
              source,
            })?
            .permissions();
          perms.set_mode(0o755);
          std::fs::set_permissions(&dest, perms).map_err(|source| FolderError::Io {
            path: dest.clone(),
            source,
          })?;
        }

        #[cfg(not(unix))]
        let _ = file_type;
      }
      EntryKind::Folder => {
        self.source.apply_folder(&dest)?;
      }
    }

    Ok(())
  }
}

/// Programmatic folder builder.
///
/// Collects entries and materializes them with [`Self::build_at`]
/// (direct write) or [`Self::build_atomic`] (temp + rename).
#[derive(Debug, Default)]
pub struct FolderBuilder {
  entries: Vec<FolderEntry>,
}

impl FolderBuilder {
  pub fn new() -> Self {
    Self::default()
  }

  pub fn add_file(
    mut self,
    path: impl Into<PathBuf>,
    file_type: FileType,
    source: ContentSource,
  ) -> Self {
    self
      .entries
      .push(FolderEntry::file(path, file_type, source));
    self
  }

  pub fn add_text_file(self, path: impl Into<PathBuf>, source: ContentSource) -> Self {
    self.add_file(path, FileType::Text, source)
  }

  pub fn add_binary_file(self, path: impl Into<PathBuf>, source: ContentSource) -> Self {
    self.add_file(path, FileType::Binary, source)
  }

  pub fn add_shell_script(self, path: impl Into<PathBuf>, source: ContentSource) -> Self {
    self.add_file(path, FileType::Shell, source)
  }

  pub fn add_folder(mut self, path: impl Into<PathBuf>, source: ContentSource) -> Self {
    self.entries.push(FolderEntry::folder(path, source));
    self
  }

  pub fn add_entry(mut self, entry: FolderEntry) -> Self {
    self.entries.push(entry);
    self
  }

  /// Build the folder at `path`, removing any existing directory first.
  pub fn build_at(self, path: &Path) -> Result<PathBuf, FolderError> {
    if path.exists() {
      std::fs::remove_dir_all(path).map_err(|source| FolderError::Io {
        path: path.to_path_buf(),
        source,
      })?;
    }
    std::fs::create_dir_all(path).map_err(|source| FolderError::Io {
      path: path.to_path_buf(),
      source,
    })?;
    for entry in &self.entries {
      entry.apply(path)?;
    }
    Ok(path.to_path_buf())
  }

  /// Build atomically: assemble into a temp directory beside `path`,
  /// then rename. Guarantees the target is either fully assembled or
  /// not present.
  pub fn build_atomic(self, path: &Path) -> Result<PathBuf, FolderError> {
    let parent = path.parent().unwrap_or(Path::new("."));
    let temp_name = format!(
      ".{}-temp-{}",
      path.file_name().unwrap_or_default().to_string_lossy(),
      std::process::id()
    );
    let temp_path = parent.join(&temp_name);

    if temp_path.exists() {
      std::fs::remove_dir_all(&temp_path).map_err(|source| FolderError::Io {
        path: temp_path.clone(),
        source,
      })?;
    }
    std::fs::create_dir_all(&temp_path).map_err(|source| FolderError::Io {
      path: temp_path.clone(),
      source,
    })?;

    for entry in &self.entries {
      if let Err(e) = entry.apply(&temp_path) {
        let _ = std::fs::remove_dir_all(&temp_path);
        return Err(e);
      }
    }

    if path.exists() {
      std::fs::remove_dir_all(path).map_err(|source| FolderError::Io {
        path: path.to_path_buf(),
        source,
      })?;
    }

    std::fs::rename(&temp_path, path).map_err(|source| FolderError::Io {
      path: path.to_path_buf(),
      source,
    })?;

    Ok(path.to_path_buf())
  }

  pub fn len(&self) -> usize {
    self.entries.len()
  }

  pub fn is_empty(&self) -> bool {
    self.entries.is_empty()
  }
}
